/**
 * Builds the filing checklist (#971) from the rule lists the two gates export, so a gate message
 * and its checklist line have one source: `PR_RULE_FIXES` (the pull request gate) and
 * `ISSUE_RULE_FIXES` (the issue check). `npm run filing-checklist` writes the page; the test
 * fails when the page differs from this output or a rule ID has no line.
 */
import fs from 'node:fs'
import { fileURLToPath } from 'node:url'

import { ISSUE_RULE_FIXES } from './issue-policy.mjs'
import { PR_RULE_FIXES } from './pr-body.mjs'

export const CHECKLIST_PATH = fileURLToPath(
  new URL('../../docs/process/filing-checklist.md', import.meta.url),
)

const lines = (fixes) => Object.entries(fixes).map(([id, fix]) => `- \`${id}\`: ${fix}`)

/** The whole page, as Prettier keeps it. */
export function renderChecklist() {
  return [
    '# Filing checklist',
    '',
    'Read this before you file an issue or open a pull request, in every session, even one given a',
    'single task. Each line is a rule ID the automatic checks report, with its one-line fix, so a',
    'filing that follows it passes the first time. The checks, not this page, are the safety net:',
    'a tool that never reads it still meets them. How they work is in',
    '[the issue check and the pull request gate](issue-and-pr-checks.md).',
    '',
    '<!-- Generated by `npm run filing-checklist` from `.github/scripts/pr-body.mjs` and `issue-policy.mjs`. Edit the fixes there, never this page. -->',
    '',
    '## Before you file an issue',
    '',
    ...lines(ISSUE_RULE_FIXES),
    '',
    '## Before you open a pull request',
    '',
    ...lines(PR_RULE_FIXES),
    '',
  ].join('\n')
}

if (process.argv[1] === fileURLToPath(import.meta.url) && process.argv.includes('--write')) {
  fs.writeFileSync(CHECKLIST_PATH, renderChecklist())
}
